// measures stay bounded per element with ch widths.
interface Props {
  lang: ReadingLanguage;
  title: string;
  description: string;
  /** Closing statement above the footer — the licence note on reader pages. */
  footerNote?: string | undefined;
  /** Where the footer's brand leads; pages with axes pass their own path. */
  homeHref?: string | undefined;
}

const { lang, title, description, footerNote, homeHref } = Astro.props;
---

<!doctype html>
<html lang={lang}>
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>{title}</title>
    <meta name="description" content={description} />
  </head>
  <body>
    <div class="frame">
      <slot />
      <SiteFooter lang={lang} note={footerNote} homeHref={homeHref} />
    </div>
